const e=JSON.parse(`[{"id":"upsc-2016-prelims-csat-a-001","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":1,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"According to the passage, which of the following factor/factors led to the adverse consequences for governance/public administration?\\n\\n1. Inability of civil services to strike a balance between internal and external accountabilities\\n\\n2. Lack of sufficient professional training to the officers of All India Services\\n\\n3. Lack of proper service benefits in civil services\\n\\n4. Lack of Constitutional provisions to define the respective roles of professional civil services vis-a-vis political executive in this context\\n\\nSelect the correct answer using the code given below :","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 4 only","d":"2, 3 and 4"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Accountability, or the lack of it, in governance generally, and civil services, in particular, is a major factor underlying the deficiencies in governance and public administration. Designing an effective framework for accountability has been a key element of the reform agenda. A fundamental issue is whether civil services should be accountable to the political executive of the day or to society at large. In other words, how should internal and external accountability be reconciled? Internal accountability is sought to be achieved by internal performance monitoring, official supervision by bodies like the Central Vigilance Commission and Comptroller and Auditor General, and judicial review of executive decisions. Articles 311 and 312 of the Indian Constitution provide job security and safeguards to the civil services, especially the All India Services. The framers of the Constitution had envisaged that provision of these safeguards would result in a civil service that is not totally subservient to the political executive but will have the strength to function in larger public interest. The need to balance internal and external accountability is thus built into the Constitution. The issue is where to draw the line. Over the years, the emphasis seems to have tilted in favour of greater internal accountability of the civil services to the political leaders of the day who in turn are expected to be externally accountable to the society at large through the election process. This system for seeking accountability to Society has not worked out, and has led to several adverse consequences for governance.\\n\\nSome special measures can be considered for improving accountability in civil services. Provisions of articles 311 and 312 should be reviewed and laws and regulations framed to ensure external accountability of civil services. The proposed Civil Services Bill seeks to address some of these requirements. The respective roles of professional civil services and the political executive should be defined so that professional managerial functions and management of civil services are depoliticized. For this purpose, effective statutory civil service boards should be created at the centre and in the states. Decentralization and devolution of authority to bring government and decision making closer to the people also helps to enhance accountability."},{"type":"paragraph","text":"According to the passage, which of the following factor/factors led to the adverse consequences for governance/public administration?"},{"type":"paragraph","text":"1. Inability of civil services to strike a balance between internal and external accountabilities"},{"type":"paragraph","text":"2. Lack of sufficient professional training to the officers of All India Services"},{"type":"paragraph","text":"3. Lack of proper service benefits in civil services"},{"type":"paragraph","text":"4. Lack of Constitutional provisions to define the respective roles of professional civil services vis-a-vis political executive in this context"},{"type":"paragraph","text":"Select the correct answer using the code given below :"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage identifies an imbalance between internal and external accountability and calls for clearly defining professional and political roles. It does not attribute the problem to inadequate training or benefits. UPSC’s final key accepts 1 and 4 only.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-002","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":2,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the passage, the following assumptions have been made :\\n\\n1. Political executive is an obstacle to the accountability of the civil services to the society\\n\\n2. In the present framework of Indian polity, the political executive is no longer accountable to the society\\n\\nWhich of these assumptions is/are valid?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Accountability, or the lack of it, in governance generally, and civil services, in particular, is a major factor underlying the deficiencies in governance and public administration. Designing an effective framework for accountability has been a key element of the reform agenda. A fundamental issue is whether civil services should be accountable to the political executive of the day or to society at large. In other words, how should internal and external accountability be reconciled? Internal accountability is sought to be achieved by internal performance monitoring, official supervision by bodies like the Central Vigilance Commission and Comptroller and Auditor General, and judicial review of executive decisions. Articles 311 and 312 of the Indian Constitution provide job security and safeguards to the civil services, especially the All India Services. The framers of the Constitution had envisaged that provision of these safeguards would result in a civil service that is not totally subservient to the political executive but will have the strength to function in larger public interest. The need to balance internal and external accountability is thus built into the Constitution. The issue is where to draw the line. Over the years, the emphasis seems to have tilted in favour of greater internal accountability of the civil services to the political leaders of the day who in turn are expected to be externally accountable to the society at large through the election process. This system for seeking accountability to Society has not worked out, and has led to several adverse consequences for governance.\\n\\nSome special measures can be considered for improving accountability in civil services. Provisions of articles 311 and 312 should be reviewed and laws and regulations framed to ensure external accountability of civil services. The proposed Civil Services Bill seeks to address some of these requirements. The respective roles of professional civil services and the political executive should be defined so that professional managerial functions and management of civil services are depoliticized. For this purpose, effective statutory civil service boards should be created at the centre and in the states. Decentralization and devolution of authority to bring government and decision making closer to the people also helps to enhance accountability."},{"type":"paragraph","text":"With reference to the passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Political executive is an obstacle to the accountability of the civil services to the society"},{"type":"paragraph","text":"2. In the present framework of Indian polity, the political executive is no longer accountable to the society"},{"type":"paragraph","text":"Which of these assumptions is/are valid?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Only assumption 1 is accepted: excessive subordination to political leaders is presented as obstructing civil servants’ direct accountability to society. The passage still expects the political executive to be accountable through elections, so assumption 2 is too absolute.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-003","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":3,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the essential message implied by this passage?","options":{"a":"Civil services are not accountable to the society they are serving","b":"Educated and enlightened persons are not taking up political leadership","c":"The framers of the Constitution did not envisage the problems being encountered by the civil services","d":"There is a need and scope for reforms to improve the accountability of civil services"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Accountability, or the lack of it, in governance generally, and civil services, in particular, is a major factor underlying the deficiencies in governance and public administration. Designing an effective framework for accountability has been a key element of the reform agenda. A fundamental issue is whether civil services should be accountable to the political executive of the day or to society at large. In other words, how should internal and external accountability be reconciled? Internal accountability is sought to be achieved by internal performance monitoring, official supervision by bodies like the Central Vigilance Commission and Comptroller and Auditor General, and judicial review of executive decisions. Articles 311 and 312 of the Indian Constitution provide job security and safeguards to the civil services, especially the All India Services. The framers of the Constitution had envisaged that provision of these safeguards would result in a civil service that is not totally subservient to the political executive but will have the strength to function in larger public interest. The need to balance internal and external accountability is thus built into the Constitution. The issue is where to draw the line. Over the years, the emphasis seems to have tilted in favour of greater internal accountability of the civil services to the political leaders of the day who in turn are expected to be externally accountable to the society at large through the election process. This system for seeking accountability to Society has not worked out, and has led to several adverse consequences for governance.\\n\\nSome special measures can be considered for improving accountability in civil services. Provisions of articles 311 and 312 should be reviewed and laws and regulations framed to ensure external accountability of civil services. The proposed Civil Services Bill seeks to address some of these requirements. The respective roles of professional civil services and the political executive should be defined so that professional managerial functions and management of civil services are depoliticized. For this purpose, effective statutory civil service boards should be created at the centre and in the states. Decentralization and devolution of authority to bring government and decision making closer to the people also helps to enhance accountability."},{"type":"paragraph","text":"Which one of the following is the essential message implied by this passage?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage diagnoses accountability failures and proposes review of safeguards, statutory boards and decentralisation. Its essential message is the need and scope for civil-service accountability reforms.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-004","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":4,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"According to the passage, which one of the following is not a means of enhancing internal accountability of civil services?","options":{"a":"Better job security and safeguards","b":"Supervision by Central Vigilance Commission","c":"Judicial review of executive decisions","d":"Seeking accountability through enhanced participation by people in decision making process"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Accountability, or the lack of it, in governance generally, and civil services, in particular, is a major factor underlying the deficiencies in governance and public administration. Designing an effective framework for accountability has been a key element of the reform agenda. A fundamental issue is whether civil services should be accountable to the political executive of the day or to society at large. In other words, how should internal and external accountability be reconciled? Internal accountability is sought to be achieved by internal performance monitoring, official supervision by bodies like the Central Vigilance Commission and Comptroller and Auditor General, and judicial review of executive decisions. Articles 311 and 312 of the Indian Constitution provide job security and safeguards to the civil services, especially the All India Services. The framers of the Constitution had envisaged that provision of these safeguards would result in a civil service that is not totally subservient to the political executive but will have the strength to function in larger public interest. The need to balance internal and external accountability is thus built into the Constitution. The issue is where to draw the line. Over the years, the emphasis seems to have tilted in favour of greater internal accountability of the civil services to the political leaders of the day who in turn are expected to be externally accountable to the society at large through the election process. This system for seeking accountability to Society has not worked out, and has led to several adverse consequences for governance.\\n\\nSome special measures can be considered for improving accountability in civil services. Provisions of articles 311 and 312 should be reviewed and laws and regulations framed to ensure external accountability of civil services. The proposed Civil Services Bill seeks to address some of these requirements. The respective roles of professional civil services and the political executive should be defined so that professional managerial functions and management of civil services are depoliticized. For this purpose, effective statutory civil service boards should be created at the centre and in the states. Decentralization and devolution of authority to bring government and decision making closer to the people also helps to enhance accountability."},{"type":"paragraph","text":"According to the passage, which one of the following is not a means of enhancing internal accountability of civil services?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Participation by people in decision-making brings accountability outward to society. The other measures relate to internal institutional accountability. Therefore enhanced public participation is not an internal mechanism.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-005","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":5,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the passage, the following assumptions have been made :\\n\\n1. Human relationships are derived from their religious traditions\\n\\n2. Human beings can be duty bound only if they believe in god\\n\\n3. Religious traditions are essential to practice and understand justice\\n\\nWhich of these assumption(s) is/are valid?","options":{"a":"1 only","b":"2 and 3 only","c":"1 and 3 only","d":"1, 2 and 3"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"In general, religious traditions stress our duty to god, or to some universal ethical principle. Our duties to one another derive from these. The religious concept of rights is primarily derived from our relationship to this divinity or principle and the implication it has on our other relationships. This correspondence between rights and duties is critical to any further understanding of justice. But, for justice to be practiced; rights and duties cannot remain formal abstraction. They must be grounded in a community (common unity) bound together by a sense of common union (communion). Even as a personal virtue, this solidarity is essential to the practice and understanding of justice."},{"type":"paragraph","text":"With reference to the passage, the following assumptions have been made :"},{"type":"paragraph","text":"1. Human relationships are derived from their religious traditions"},{"type":"paragraph","text":"2. Human beings can be duty bound only if they believe in god"},{"type":"paragraph","text":"3. Religious traditions are essential to practice and understand justice"},{"type":"paragraph","text":"Which of these assumption(s) is/are valid?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage derives duties and relationships from religious traditions or an ethical principle, supporting assumption 1. It does not require belief in God alone or claim religion is the only possible basis of justice.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-006","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":6,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which one of the following is the crux of this passage?","options":{"a":"Our duties to one another derive from our religious traditions","b":"Having relationship to the divine principle is a great virtue","c":"Balance between rights and duties is crucial to the delivery of justice in a society","d":"Religious concept of rights is primarily derived from our relationship to god"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"In general, religious traditions stress our duty to god, or to some universal ethical principle. Our duties to one another derive from these. The religious concept of rights is primarily derived from our relationship to this divinity or principle and the implication it has on our other relationships. This correspondence between rights and duties is critical to any further understanding of justice. But, for justice to be practiced; rights and duties cannot remain formal abstraction. They must be grounded in a community (common unity) bound together by a sense of common union (communion). Even as a personal virtue, this solidarity is essential to the practice and understanding of justice."},{"type":"paragraph","text":"Which one of the following is the crux of this passage?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The passage’s focus is the correspondence between rights and duties, grounded in community and solidarity. Their balance is crucial to delivering justice in society.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-007","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":7,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"A ate grapes and pineapple; B ate grapes and oranges; C ate oranges, pineapple and apple; D ate grapes, apple and pineapple. After taking fruits, B and C fell sick. In the light of the above facts, it can be said that the cause of sickness was:","options":{"a":"Apple","b":"Pineapple","c":"Grapes","d":"Oranges"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A ate grapes and pineapple; B ate grapes and oranges; C ate oranges, pineapple and apple; D ate grapes, apple and pineapple. After taking fruits, B and C fell sick. In the light of the above facts, it can be said that the cause of sickness was:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Only B and C ate oranges, and these are the two who fell sick. The other fruits were also eaten by A or D, who did not fall sick. Oranges are the common suspected cause.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-008","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":8,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Consider the following statements.\\n\\n1. The rate of population growth is increasing in the country\\n\\n2. The death rate is declining faster in the country compared to birth rate\\n\\n3. The birth rate is declining faster in the country compared to death rate\\n\\n4. Rural-urban migration is taking place regularly in the country\\n\\nWhich one of the following conclusions may be true in the light of the above facts?","options":{"a":"The rate of population growth is increasing due to rural-urban migration","b":"The rate of population growth is increasing due to decline in death rate only","c":"The rate of population growth is increasing due to increase in birth rate only","d":"The rate of population growth is increasing due to faster decline in death rate than in birth rate"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements."},{"type":"paragraph","text":"1. The rate of population growth is increasing in the country"},{"type":"paragraph","text":"2. The death rate is declining faster in the country compared to birth rate"},{"type":"paragraph","text":"3. The birth rate is declining faster in the country compared to death rate"},{"type":"paragraph","text":"4. Rural-urban migration is taking place regularly in the country"},{"type":"paragraph","text":"Which one of the following conclusions may be true in the light of the above facts?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Population growth depends on the gap between birth and death rates. A faster decline in death rate than birth rate widens that gap. Internal rural–urban migration does not itself increase national population.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-009","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":9,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"A person X was driving in a place where all roads ran either north-south or east-west, forming a grid. Roads are at a distance of 1 km from each other in a parallel. He started at the intersection of two roads, drove 3 km north, 3 km west and 4 km south. Which further route could bring him back to his starting point, if the same route is not repeated?","options":{"a":"3 km east, then 2 km south","b":"3 km east, then 1 km north","c":"1 km north, then 2 km west","d":"3 km south, then 1 km north"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A person X was driving in a place where all roads ran either north-south or east-west, forming a grid. Roads are at a distance of 1 km from each other in a parallel. He started at the intersection of two roads, drove 3 km north, 3 km west and 4 km south. Which further route could bring him back to his starting point, if the same route is not repeated?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Using the start as (0,0), the route ends at (−3,−1). Travelling 3 km east and then 1 km north returns to the start along unused segments.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-010","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":10,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Consider the following statement:\\n\\n\\"We shall go either for a picnic or for trekking\\".\\n\\nWhich of the following, if true, would falsify this claim?","options":{"a":"We go for a picnic but not for trekking","b":"Activities such as picnic and trekking are encouraged by the health authorities","c":"We go for trekking and not for picnic","d":"We do not go either for picnic or for trekking"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statement:"},{"type":"paragraph","text":"\\"We shall go either for a picnic or for trekking\\"."},{"type":"paragraph","text":"Which of the following, if true, would falsify this claim?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The claim promises at least one of the two activities. Going for neither a picnic nor trekking directly falsifies it.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-011","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":11,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"There were 50 faculty members comprising 30 males and the rest females. No male faculty member knew music, but many of the female faculty members did. The Head of the institution invited six faculty members to a tea party by draw of lots. At the party it was discovered that no members knew music. The conclusion is that:","options":{"a":"the party comprised male faculty members only","b":"the party comprised only those female faculty members who could not give renderings in music","c":"the party comprised both male and female faculty members","d":"nothing can be said about the gender composition of the party"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"There were 50 faculty members comprising 30 males and the rest females. No male faculty member knew music, but many of the female faculty members did. The Head of the institution invited six faculty members to a tea party by draw of lots. At the party it was discovered that no members knew music. The conclusion is that:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Some women do not know music, while no men do. A group with no musical members could therefore contain men, non-musical women or both. Its gender composition cannot be determined.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-012","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":12,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Five people A, B, C, D and E are seated about a round table. Every chair is spaced equidistant from adjacent chairs.\\n\\n(i) C is seated next to A\\n\\n(ii) A is seated two seats from D\\n\\n(iii) B is not seated next to A\\n\\nOn the basis of above information, which of the following must be true?\\n\\n1. D is seated next to B\\n\\n2. E is seated next to A\\n\\n3. D and C are separated by two seats\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 only","b":"1 and 2 only","c":"3 only","d":"Neither 1 nor 2 nor 3"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Five people A, B, C, D and E are seated about a round table. Every chair is spaced equidistant from adjacent chairs."},{"type":"paragraph","text":"(i) C is seated next to A\\n\\n(ii) A is seated two seats from D\\n\\n(iii) B is not seated next to A"},{"type":"paragraph","text":"On the basis of above information, which of the following must be true?"},{"type":"paragraph","text":"1. D is seated next to B"},{"type":"paragraph","text":"2. E is seated next to A"},{"type":"paragraph","text":"3. D and C are separated by two seats"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"With A fixed, every arrangement satisfying the constraints puts E next to A and D next to B. D and C’s separation is not fixed. Only statements 1 and 2 must be true.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-013","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":13,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"There are five hobby clubs in a college —photography, yachting, chess, electronics and gardening. The gardening group meets every second day, the electronics group meets every third day, the chess group meets every fourth day, the yachting group meets every fifth day and the photography group meets every sixth day. How many times do all the five groups meet on the same day within 180 days?","options":{"a":"5","b":"18","c":"10","d":"3"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"There are five hobby clubs in a college —photography, yachting, chess, electronics and gardening. The gardening group meets every second day, the electronics group meets every third day, the chess group meets every fourth day, the yachting group meets every fifth day and the photography group meets every sixth day. How many times do all the five groups meet on the same day within 180 days?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"All groups coincide every LCM(2,3,4,5,6)=60 days. Within 180 days they meet together on days 60, 120 and 180: three times.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-014","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":14,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"There are some nectar-filled flowers on a tree and some bees are hovering on it. If one bee lands on each flower, one bee will be left out. If two bees land on each flower, one flower will be left out. The number of flowers and bees respectively are:","options":{"a":"2 and 4","b":"3 and 2","c":"3 and 4","d":"4 and 3"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"There are some nectar-filled flowers on a tree and some bees are hovering on it. If one bee lands on each flower, one bee will be left out. If two bees land on each flower, one flower will be left out. The number of flowers and bees respectively are:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Let flowers be f and bees b. The conditions give b=f+1 and b=2(f−1). Therefore f=3 and b=4.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-015","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":15,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Who is the doctor?","options":{"a":"T","b":"P","c":"Q","d":"R"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the following information and answer the five items that follow:\\n\\nThere are five persons in a group — P, Q, R, S and T. The group has one doctor, one lawyer and one artist. P and S are unmarried students. T is a man married to one of the group members. Q is the brother of P and is neither doctor nor artist. R is not doctor."},{"type":"paragraph","text":"Who is the doctor?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"P and S are students, Q is not the doctor, and R is not the doctor. The remaining person T must be the doctor.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-016","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":16,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Who is the artist?","options":{"a":"P","b":"Q","c":"R","d":"T"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the following information and answer the five items that follow:\\n\\nThere are five persons in a group — P, Q, R, S and T. The group has one doctor, one lawyer and one artist. P and S are unmarried students. T is a man married to one of the group members. Q is the brother of P and is neither doctor nor artist. R is not doctor."},{"type":"paragraph","text":"Who is the artist?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"T is the doctor, Q is neither doctor nor artist, and P and S are students. Therefore R is the artist.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-017","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":17,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Who is the spouse of R?","options":{"a":"P","b":"T","c":"Q","d":"S"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the following information and answer the five items that follow:\\n\\nThere are five persons in a group — P, Q, R, S and T. The group has one doctor, one lawyer and one artist. P and S are unmarried students. T is a man married to one of the group members. Q is the brother of P and is neither doctor nor artist. R is not doctor."},{"type":"paragraph","text":"Who is the spouse of R?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"P and S are unmarried students, and Q is identified as a man. T is a married man, so R is his spouse.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-018","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":18,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Who is the lawyer?","options":{"a":"P","b":"Q","c":"R","d":"S"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the following information and answer the five items that follow:\\n\\nThere are five persons in a group — P, Q, R, S and T. The group has one doctor, one lawyer and one artist. P and S are unmarried students. T is a man married to one of the group members. Q is the brother of P and is neither doctor nor artist. R is not doctor."},{"type":"paragraph","text":"Who is the lawyer?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The three professionals are Q, R and T. Since T is the doctor and R the artist, Q must be the lawyer.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-019","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":19,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Who of the following is definitely a man?","options":{"a":"P","b":"S","c":"Q","d":"None of the above"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the following information and answer the five items that follow:\\n\\nThere are five persons in a group — P, Q, R, S and T. The group has one doctor, one lawyer and one artist. P and S are unmarried students. T is a man married to one of the group members. Q is the brother of P and is neither doctor nor artist. R is not doctor."},{"type":"paragraph","text":"Who of the following is definitely a man?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Q is explicitly P’s brother, so Q is definitely a man. P’s and S’s sexes are not established by the information.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-020","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":20,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"There is an order of 19000 quantity of a particular product from a customer. The firm produces 1000 quantity of that product per day out of which 5% are unfit for sale. In how many days will the order be completed?","options":{"a":"18","b":"19","c":"20","d":"22"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"There is an order of 19000 quantity of a particular product from a customer. The firm produces 1000 quantity of that product per day out of which 5% are unfit for sale. In how many days will the order be completed?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Usable output per day is 1,000×0.95 = 950 units. Producing 19,000 saleable units takes 19,000/950 = 20 days.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-021","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":21,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What is/are the present constraint/constraints in using biomass as fuel for power generation?\\n\\n1. Lack of sustainable supply of biomass\\n\\n2. Biomass production competes with food production\\n\\n3. Bio-energy may not always be low carbon on a life-cycle basis\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Biomass as fuel for power, heat, and transport has the highest mitigation potential of all renewable sources. It comes from agriculture and forest residues as well as from energy crops. The biggest challenge in using biomass residues is a long-term reliable supply delivered to the power plant at reasonable costs; the key problems are logistical constraints and the costs of fuel collection. Energy crops, if not managed properly, compete with food production and may have undesirable impacts on food prices. Biomass production is also sensitive to the physical impacts of a changing climate.\\n\\nProjections of the future role of biomass are probably overestimated, given the limits to the sustainable biomass supply, unless breakthrough technologies substantially increase productivity. Climate-energy models project that biomass use could increase nearly four-fold to around 150 — 200 exajoules, almost a quarter of world primary energy in 2050. However the maximum sustainable technical potential of biomass resources (both residues and energy crops) without disruption of food and forest resources ranges from 80 — 170 exajoules a year by 2050, and only part of this is realistically and economically feasible. In addition, some climate models rely on biomass-based carbon capture and storage, an unproven technology, to achieve negative emissions and to buy some time during the first half of the century.\\n\\nSome liquid biofuels such as corn-based ethanol, mainly for transport, may aggravate rather than ameliorate carbon emissions on a life-cycle basis. Second generation biofuels, based on ligno-cellulosic feedstocks — such as straw, bagasse, grass and wood — hold the promise of sustainable production that is high-yielding and emit low levels of greenhouse gases, but these are still in the R & D stage."},{"type":"paragraph","text":"What is/are the present constraint/constraints in using biomass as fuel for power generation?"},{"type":"paragraph","text":"1. Lack of sustainable supply of biomass"},{"type":"paragraph","text":"2. Biomass production competes with food production"},{"type":"paragraph","text":"3. Bio-energy may not always be low carbon on a life-cycle basis"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"All three constraints appear in the passage: sustainable biomass supply is limited, energy crops can compete with food, and some fuels worsen life-cycle carbon emissions.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-022","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":22,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following can lead to food security problem?\\n\\n1. Using agricultural and forest residues as feedstock for power generation\\n\\n2. Using biomass for carbon capture and storage\\n\\n3. Promoting the cultivation of energy crops\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Biomass as fuel for power, heat, and transport has the highest mitigation potential of all renewable sources. It comes from agriculture and forest residues as well as from energy crops. The biggest challenge in using biomass residues is a long-term reliable supply delivered to the power plant at reasonable costs; the key problems are logistical constraints and the costs of fuel collection. Energy crops, if not managed properly, compete with food production and may have undesirable impacts on food prices. Biomass production is also sensitive to the physical impacts of a changing climate.\\n\\nProjections of the future role of biomass are probably overestimated, given the limits to the sustainable biomass supply, unless breakthrough technologies substantially increase productivity. Climate-energy models project that biomass use could increase nearly four-fold to around 150 — 200 exajoules, almost a quarter of world primary energy in 2050. However the maximum sustainable technical potential of biomass resources (both residues and energy crops) without disruption of food and forest resources ranges from 80 — 170 exajoules a year by 2050, and only part of this is realistically and economically feasible. In addition, some climate models rely on biomass-based carbon capture and storage, an unproven technology, to achieve negative emissions and to buy some time during the first half of the century.\\n\\nSome liquid biofuels such as corn-based ethanol, mainly for transport, may aggravate rather than ameliorate carbon emissions on a life-cycle basis. Second generation biofuels, based on ligno-cellulosic feedstocks — such as straw, bagasse, grass and wood — hold the promise of sustainable production that is high-yielding and emit low levels of greenhouse gases, but these are still in the R & D stage."},{"type":"paragraph","text":"Which of the following can lead to food security problem?"},{"type":"paragraph","text":"1. Using agricultural and forest residues as feedstock for power generation"},{"type":"paragraph","text":"2. Using biomass for carbon capture and storage"},{"type":"paragraph","text":"3. Promoting the cultivation of energy crops"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Promoting energy crops can compete for land and resources with food production. The passage does not identify residues or carbon capture alone as causing food insecurity. Thus 3 only.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-023","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":23,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"In the context of using biomass, which of the following is/are the characteristic/characteristics of the sustainable production of biofuel?\\n\\n1. Biomass as a fuel for power generation could meet all the primary energy requirements of the world by 2050\\n\\n2. Biomass as a fuel for power generation does not necessarily disrupt food and forest resources\\n\\n3. Biomass as a fuel for power generation could help in achieving negative emissions, given certain nascent technologies\\n\\nSelect the correct answer using the code given below:","options":{"a":"1 and 2 only","b":"3 only","c":"2 and 3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Biomass as fuel for power, heat, and transport has the highest mitigation potential of all renewable sources. It comes from agriculture and forest residues as well as from energy crops. The biggest challenge in using biomass residues is a long-term reliable supply delivered to the power plant at reasonable costs; the key problems are logistical constraints and the costs of fuel collection. Energy crops, if not managed properly, compete with food production and may have undesirable impacts on food prices. Biomass production is also sensitive to the physical impacts of a changing climate.\\n\\nProjections of the future role of biomass are probably overestimated, given the limits to the sustainable biomass supply, unless breakthrough technologies substantially increase productivity. Climate-energy models project that biomass use could increase nearly four-fold to around 150 — 200 exajoules, almost a quarter of world primary energy in 2050. However the maximum sustainable technical potential of biomass resources (both residues and energy crops) without disruption of food and forest resources ranges from 80 — 170 exajoules a year by 2050, and only part of this is realistically and economically feasible. In addition, some climate models rely on biomass-based carbon capture and storage, an unproven technology, to achieve negative emissions and to buy some time during the first half of the century.\\n\\nSome liquid biofuels such as corn-based ethanol, mainly for transport, may aggravate rather than ameliorate carbon emissions on a life-cycle basis. Second generation biofuels, based on ligno-cellulosic feedstocks — such as straw, bagasse, grass and wood — hold the promise of sustainable production that is high-yielding and emit low levels of greenhouse gases, but these are still in the R & D stage."},{"type":"paragraph","text":"In the context of using biomass, which of the following is/are the characteristic/characteristics of the sustainable production of biofuel?"},{"type":"paragraph","text":"1. Biomass as a fuel for power generation could meet all the primary energy requirements of the world by 2050"},{"type":"paragraph","text":"2. Biomass as a fuel for power generation does not necessarily disrupt food and forest resources"},{"type":"paragraph","text":"3. Biomass as a fuel for power generation could help in achieving negative emissions, given certain nascent technologies"},{"type":"paragraph","text":"Select the correct answer using the code given below:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Sustainable biomass need not disrupt food and forests, and emerging capture-and-storage technologies may yield negative emissions. It cannot meet all projected global primary energy requirements. Thus 2 and 3 only.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-024","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":24,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the passage, following assumptions have been made:\\n\\n1. Some climate-energy models suggest that the use of biomass as a fuel for power generation helps in mitigating greenhouse gas emissions\\n\\n2. It is not possible to use biomass as a fuel for power generation without disrupting food and forest resources\\n\\nWhich of these assumptions is/are valid?","options":{"a":"1 only","b":"2 only","c":"Both 1 and 2","d":"Neither 1 nor 2"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Biomass as fuel for power, heat, and transport has the highest mitigation potential of all renewable sources. It comes from agriculture and forest residues as well as from energy crops. The biggest challenge in using biomass residues is a long-term reliable supply delivered to the power plant at reasonable costs; the key problems are logistical constraints and the costs of fuel collection. Energy crops, if not managed properly, compete with food production and may have undesirable impacts on food prices. Biomass production is also sensitive to the physical impacts of a changing climate.\\n\\nProjections of the future role of biomass are probably overestimated, given the limits to the sustainable biomass supply, unless breakthrough technologies substantially increase productivity. Climate-energy models project that biomass use could increase nearly four-fold to around 150 — 200 exajoules, almost a quarter of world primary energy in 2050. However the maximum sustainable technical potential of biomass resources (both residues and energy crops) without disruption of food and forest resources ranges from 80 — 170 exajoules a year by 2050, and only part of this is realistically and economically feasible. In addition, some climate models rely on biomass-based carbon capture and storage, an unproven technology, to achieve negative emissions and to buy some time during the first half of the century.\\n\\nSome liquid biofuels such as corn-based ethanol, mainly for transport, may aggravate rather than ameliorate carbon emissions on a life-cycle basis. Second generation biofuels, based on ligno-cellulosic feedstocks — such as straw, bagasse, grass and wood — hold the promise of sustainable production that is high-yielding and emit low levels of greenhouse gases, but these are still in the R & D stage."},{"type":"paragraph","text":"With reference to the passage, following assumptions have been made:"},{"type":"paragraph","text":"1. Some climate-energy models suggest that the use of biomass as a fuel for power generation helps in mitigating greenhouse gas emissions"},{"type":"paragraph","text":"2. It is not possible to use biomass as a fuel for power generation without disrupting food and forest resources"},{"type":"paragraph","text":"Which of these assumptions is/are valid?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The models described envisage biomass helping mitigate emissions, so assumption 1 is valid. The passage explicitly considers a sustainable supply without disrupting food or forests, contradicting assumption 2.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-025","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":25,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which among the following is the most logical and critical inference that can be made from the above passage?","options":{"a":"In our agricultural practices, we have become heavily dependent on expensive chemical fertilizers and toxic pesticides only due to green revolution","b":"Monocropping vast fields with high-yield varieties is possible due to green revolution","c":"Monocropping with high-yield varieties is the only way to ensure food security to millions","d":"Green revolution can pose a threat to biodiversity in food supply and food security in the long run"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"We are witnessing a dangerous dwindling of biodiversity in our food supply. The green revolution is a mixed blessing. Over time farmers have come to rely heavily on broadly adapted, high yield crops to the exclusion of varieties adapted to the local conditions. Monocropping vast fields with the same genetically uniform seeds helps boost yield and meet immediate hunger needs. Yet high-yield varieties are also genetically weaker crops that require expensive chemical fertilizers and toxic pesticides. In our focus on increasing the amount of food we produce today, we have accidentally put ourselves at risk for food shortages in future."},{"type":"paragraph","text":"Which among the following is the most logical and critical inference that can be made from the above passage?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Reliance on genetically uniform high-yield crops reduces diversity and creates future vulnerability despite present yield benefits. The inference is a long-term risk to biodiversity and food security.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-026","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":26,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A class starts at 11:00 am and lasts till 2:27 pm. Four periods of equal duration are held during this interval. After every period, a rest of 5 minutes is given to the students. The exact duration of each period is:","options":{"a":"48 minutes","b":"50 minutes","c":"51 minutes","d":"53 minutes"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A class starts at 11:00 am and lasts till 2:27 pm. Four periods of equal duration are held during this interval. After every period, a rest of 5 minutes is given to the students. The exact duration of each period is:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The interval is 207 minutes. The three rests between four periods take 15 minutes, leaving 192 minutes of class time. Each period is 192/4 = 48 minutes.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-027","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":27,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"Four friends A, B, C and D need to cross a bridge. A maximum of two persons can cross it at a time. It is night and they just have one lamp. Persons that cross the bridge must carry the lamp to find the way. A pair must walk together at the speed of slower person. After crossing the bridge, the person having faster speed in the pair will return with the lamp each time to accompany another person in the group. Finally, the lamp has to be returned at the original place and the person who returns the lamp has to cross the bridge again without lamp. To cross the bridge, the time taken by them is as follows : A: 1 minute, B: 2 minutes, C: 7 minutes and D: 10 minutes. What is the total minimum time required by all the friends to cross the bridge?","options":{"a":"23 minutes","b":"22 minutes","c":"21 minutes","d":"20 minutes"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Four friends A, B, C and D need to cross a bridge. A maximum of two persons can cross it at a time. It is night and they just have one lamp. Persons that cross the bridge must carry the lamp to find the way. A pair must walk together at the speed of slower person. After crossing the bridge, the person having faster speed in the pair will return with the lamp each time to accompany another person in the group. Finally, the lamp has to be returned at the original place and the person who returns the lamp has to cross the bridge again without lamp. To cross the bridge, the time taken by them is as follows : A: 1 minute, B: 2 minutes, C: 7 minutes and D: 10 minutes. What is the total minimum time required by all the friends to cross the bridge?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Under the stated rule the faster member of each pair returns, so the fastest person A escorts the others. The minimum sequence costs 2+1+7+1+10+1+1 = 23 minutes, including returning the lamp and A’s final lamp-free crossing.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-028","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":28,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"30g of sugar was mixed in 180 ml water in a vessel A, 40 g of sugar Was mixed in 280 ml of water in vessel B and 20 g of sugar was mixed in 100 ml of water in vessel C. The solution in vessel B is","options":{"a":"sweeter than that in C","b":"sweeter than that in A","c":"as sweet as that in C","d":"less sweet than that in C"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"30g of sugar was mixed in 180 ml water in a vessel A, 40 g of sugar Was mixed in 280 ml of water in vessel B and 20 g of sugar was mixed in 100 ml of water in vessel C. The solution in vessel B is"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Sugar-to-water ratios are A=30/180=1/6, B=40/280=1/7 and C=20/100=1/5. B has the lowest concentration and is less sweet than C.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-029","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":29,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"In aid of charity, every student in a class contributes as many rupees as the number of students in that class. With the additional contribution of Rs. 2 by one student only, the total collection is Rs. 443. Then how many students are there in the class?","options":{"a":"12","b":"21","c":"43","d":"45"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"In aid of charity, every student in a class contributes as many rupees as the number of students in that class. With the additional contribution of Rs. 2 by one student only, the total collection is Rs. 443. Then how many students are there in the class?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"If there are n students, the main contribution is n² rupees. Thus n²+2=443, giving n²=441 and n=21.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-030","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":30,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"Anita's mathematics test had 70 problems carrying equal marks i.e., 10 arithmetic, 30 algebra and 30 geometry. Although she answered 70% of the arithmetic, 40% of the algebra and 60% of the geometry problems correctly, she did not pass the test because she got less than 60% marks. The number of more questions she would have to answer correctly to earn a 60% passing marks is:","options":{"a":"1","b":"5","c":"7","d":"9"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Anita's mathematics test had 70 problems carrying equal marks i.e., 10 arithmetic, 30 algebra and 30 geometry. Although she answered 70% of the arithmetic, 40% of the algebra and 60% of the geometry problems correctly, she did not pass the test because she got less than 60% marks. The number of more questions she would have to answer correctly to earn a 60% passing marks is:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Correct answers total 0.70×10+0.40×30+0.60×30 = 37. Passing requires 0.60×70 = 42, so 5 additional answers are needed.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-031","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":31,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"In a class, there are 18 very tall boys. If these constitute three-fourths of the boys and the total number of boys is two-thirds of the total number of students in the class, what is the number of girls in the class?","options":{"a":"6","b":"12","c":"18","d":"21"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"In a class, there are 18 very tall boys. If these constitute three-fourths of the boys and the total number of boys is two-thirds of the total number of students in the class, what is the number of girls in the class?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Total boys = 18÷(3/4)=24. They form two-thirds of the class, so total students = 36 and girls = 12.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-032","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":32,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Consider the following statements:\\n\\n1. Either A and B are of the same age or A is older than B\\n\\n2. Either C and D are of the same age or D is older than C\\n\\n3. B is older than C\\n\\nWhich of the following conclusions can be drawn from the above statements?","options":{"a":"A is older than B","b":"B and D are of the same age","c":"D is older than C","d":"A is older than C"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Consider the following statements:"},{"type":"paragraph","text":"1. Either A and B are of the same age or A is older than B"},{"type":"paragraph","text":"2. Either C and D are of the same age or D is older than C"},{"type":"paragraph","text":"3. B is older than C"},{"type":"paragraph","text":"Which of the following conclusions can be drawn from the above statements?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"A is at least as old as B, and B is older than C. Therefore A is older than C. The statements do not fix strict comparisons between A and B or D and C.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-033","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":33,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"The monthly average salary paid to all the employees of a company was Rs. 5000. The monthly average salary paid to male and female employees was Rs. 5200 and Rs. 4200 respectively. Then the percentage of males employed in the company is","options":{"a":"75%","b":"80%","c":"85%","d":"90%"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"The monthly average salary paid to all the employees of a company was Rs. 5000. The monthly average salary paid to male and female employees was Rs. 5200 and Rs. 4200 respectively. Then the percentage of males employed in the company is"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"If the male fraction is m, then 5,200m+4,200(1−m)=5,000. Hence 1,000m=800, so males make up 80 percent.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-034","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":34,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Which one of the following boxes contains the golf ball?","options":{"a":"F","b":"E","c":"D","d":"None of the above"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the given information and answer the three items that follow.\\n\\nSix boxes A, B, C, D, E and F have been painted with six different colours viz., violet, indigo, blue, green, yellow and orange and arranged from left to right (not necessarily either kept or painted with the colours in the same order). Each box contains a ball of any one of the following six games: cricket, hockey, tennis, golf, football and volleyball (not necessarily in the same order). The golf ball is in violet box and is not in the box D. The box A which contains tennis ball is orange in colour and is at the extreme right. The hockey ball is neither in box D nor in box E. The box C having cricket ball is painted green. The hockey ball is neither in the box painted blue nor in the box painted yellow. The box C is fifth from right and next to box B. The box B contains volleyball. The box containing the hockey ball is between the boxes containing golf ball and volleyball."},{"type":"paragraph","text":"Which one of the following boxes contains the golf ball?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The hockey box must be F, between the golf and volleyball boxes. The golf ball cannot be in D, A, B or C, and F has hockey, leaving E for golf.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-035","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":35,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"Which of the following statements is/are correct?","options":{"a":"D is painted yellow","b":"F is painted indigo","c":"B is painted blue","d":"All of the above"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the given information and answer the three items that follow.\\n\\nSix boxes A, B, C, D, E and F have been painted with six different colours viz., violet, indigo, blue, green, yellow and orange and arranged from left to right (not necessarily either kept or painted with the colours in the same order). Each box contains a ball of any one of the following six games: cricket, hockey, tennis, golf, football and volleyball (not necessarily in the same order). The golf ball is in violet box and is not in the box D. The box A which contains tennis ball is orange in colour and is at the extreme right. The hockey ball is neither in box D nor in box E. The box C having cricket ball is painted green. The hockey ball is neither in the box painted blue nor in the box painted yellow. The box C is fifth from right and next to box B. The box B contains volleyball. The box containing the hockey ball is between the boxes containing golf ball and volleyball."},{"type":"paragraph","text":"Which of the following statements is/are correct?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"E is violet with golf, C green with cricket and A orange with tennis. Hockey cannot be in blue or yellow, so F is indigo. B and D can interchange blue and yellow; only F being indigo is certain.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-036","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":36,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"The football is in the box of which colour?","options":{"a":"Yellow","b":"Indigo","c":"Cannot be determined as data are inadequate","d":"Blue"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"passage","text":"Consider the given information and answer the three items that follow.\\n\\nSix boxes A, B, C, D, E and F have been painted with six different colours viz., violet, indigo, blue, green, yellow and orange and arranged from left to right (not necessarily either kept or painted with the colours in the same order). Each box contains a ball of any one of the following six games: cricket, hockey, tennis, golf, football and volleyball (not necessarily in the same order). The golf ball is in violet box and is not in the box D. The box A which contains tennis ball is orange in colour and is at the extreme right. The hockey ball is neither in box D nor in box E. The box C having cricket ball is painted green. The hockey ball is neither in the box painted blue nor in the box painted yellow. The box C is fifth from right and next to box B. The box B contains volleyball. The box containing the hockey ball is between the boxes containing golf ball and volleyball."},{"type":"paragraph","text":"The football is in the box of which colour?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"After identifying A, C, E and F, the remaining boxes B and D receive blue and yellow, but their colours are not fixed. The football’s colour therefore cannot be determined.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-037","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":37,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"Two numbers X and Y are respectively 20% and 28% less than a third number Z. By what percentage is the number Y less than the number X ?","options":{"a":"12%","b":"10%","c":"9%","d":"8%"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"Two numbers X and Y are respectively 20% and 28% less than a third number Z. By what percentage is the number Y less than the number X ?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"X=0.80Z and Y=0.72Z. The decrease relative to X is (0.80−0.72)/0.80 = 0.10, or 10 percent.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-038","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":38,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A daily train is to be introduced between station A and station B starting from each end at 6 AM and the journey is to be completed in 42 hours. What is the number of trains needed in order to maintain the Shuttle Service?","options":{"a":"2","b":"3","c":"4","d":"7"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A daily train is to be introduced between station A and station B starting from each end at 6 AM and the journey is to be completed in 42 hours. What is the number of trains needed in order to maintain the Shuttle Service?"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Each train takes 42 hours to reach the opposite end, so it can make its next scheduled departure 48 hours after the previous one. Two trains at each end, four in total, maintain daily 6 a.m. departures.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-039","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":39,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude","question":"A piece of tin is in the form of a rectangle having length 12 cm and width 8 cm. This is used to construct a closed cube. The side of the cube is:","options":{"a":"2 cm","b":"3 cm","c":"4 cm","d":"6 cm"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"A piece of tin is in the form of a rectangle having length 12 cm and width 8 cm. This is used to construct a closed cube. The side of the cube is:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"The tin has area 12×8=96 cm². A closed cube has area 6s², so s²=16 and the side is 4 cm.","concept":"Quantitative aptitude","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}},{"id":"upsc-2016-prelims-csat-a-040","year":2016,"stage":"CSAT","paper":"CSAT Paper II","number":40,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Analytical reasoning","question":"In a question paper there are five questions to be attempted and answer to each question has two choices - True (T) or False (F). It is given that no two candidates have given the answers to the five questions in an identical sequence. For this to happen the maximum number of candidates is:","options":{"a":"10","b":"18","c":"26","d":"32"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://iasexamportal.com/ias-pre/papers/answer-keys-upsc-2016-csat-paper-2","keyUrl":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1","page":0,"blocks":[{"type":"paragraph","text":"In a question paper there are five questions to be attempted and answer to each question has two choices - True (T) or False (F). It is given that no two candidates have given the answers to the five questions in an identical sequence. For this to happen the maximum number of candidates is:"}],"sourceTitle":"UPSC CSE 2016 CSAT Paper II · Series A","explanation":{"justification":"Each of five answers has two choices. The number of distinct answer sequences is 2^5 = 32, the maximum possible candidates without duplication.","concept":"Analytical reasoning","references":[{"title":"UPSC CSE 2016 final CSAT answer key · Series A","url":"https://forumias.com/blog/wp-content/uploads/2022/02/CSP_16_GS_Paper_II.pdf#page=1"}]}}]`);export{e as p};
